// An invoice the store holds without lines (a free plan's invoice before it had a line) used to panic the list and get
// answers with "index out of range [0] with length 0"; it is shown with an empty description.
func TestInvoiceWithoutLines(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: e.Acme.ID, CustomerID: c.ID, Currency: money.USD}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	var list struct{ Items []struct{ ID, Description string } }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Acme.Key, nil, &list)
	if len(list.Items) != 1 || list.Items[0].ID != inv.ID || list.Items[0].Description != "" {
		t.Fatalf("invoices = %+v", list)
	}
	var got struct{ ID, Description string }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID, e.Acme.Key, nil, &got)
	if got.ID != inv.ID || got.Description != "" {
		t.Fatalf("invoice = %+v", got)
	}
	var paid struct {
		Invoice struct {
			Status store.InvoiceStatus
			Description string
		} `json:"invoice"`
	}
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+inv.ID+"/pay", e.Acme.Key, nil, &paid)
	if paid.Invoice.Status != store.InvoicePaid || paid.Invoice.Description != "" {
		t.Fatalf("paid = %+v", paid)
	}
}
EOF
