71	// listInvoices lists the organization's invoices, oldest first, optionally only those of ?customer_id=, ?subscription_id=
72	// or with ?status=.
73	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
74		pg, ok := parsePage(w, r)
75		if !ok {
76			return
77		}
78		q := r.URL.Query()
79		status := store.InvoiceStatus(q.Get("status"))
80		if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
81			writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
82			return
83		}
84		invs := s.store.ListInvoices(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status})
85		customers := s.store.Customers(p.OrgID)
86		views := make([]invoiceView, 0, len(invs))
87		for _, inv := range invs {
88			views = append(views, newInvoiceView(inv, findCustomer(customers, inv.CustomerID)))
89		}
90		items, next := pageOf(views, invoiceViewKey, pg)
91		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
92	}
