127	func (s *Server) getInvoice(w http.ResponseWriter, r *http.Request, p auth.Principal) {
128		inv, ok := s.store.Invoice(p.OrgID, r.PathValue("id"))
129		if !ok {
130			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
131			return
132		}
133		writeJSON(w, http.StatusOK, s.viewInvoice(inv))
134	}
