136	// getInvoiceLines answers an invoice's lines with each line's amount, for the dashboard's invoice table.
137	func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
138		inv, ok := s.store.InvoiceByID(r.PathValue("id"))
139		if !ok {
140			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
141			return
142		}
143		type lineView struct {
144			store.Line
145			Amount int64 `json:"amount"`
146		}
147		items := []lineView{}
148		for _, l := range inv.Lines {
149			items = append(items, lineView{Line: l, Amount: l.Amount()})
150		}
