208	func (s *Server) listPayments(w http.ResponseWriter, r *http.Request, p auth.Principal) {
209		writeJSON(w, http.StatusOK, list{Items: s.store.Payments(p.OrgID, r.URL.Query().Get("invoice_id"))})
210	}
